#include <vector>
#include <algorithm>

class Solution {
    struct Fenwick {
        int n;
        std::vector<long long> tree;
        Fenwick(int n) : n(n), tree(n + 1, 0) {}
        void update(int idx, int delta) {
            for (++idx; idx <= n; idx += idx & (-idx)) tree[idx] += delta;
        }
        long long query(int idx) {
            long long s = 0;
            for (++idx; idx > 0; idx -= idx & (-idx)) s += tree[idx];
            return s;
        }
        long long rangeQuery(int l, int r) {
            return query(r) - query(l - 1);
        }
    };
public:
    std::vector<long long> goodSubsequenceQueries(std::vector<int>& nums, std::vector<std::vector<int>>& queries) {
        int n = nums.size(), q = queries.size();
        Fenwick bit(n);
        std::vector<int> qIdx(q);
        for (int i = 0; i < q; ++i) qIdx[i] = i;
        std::sort(qIdx.begin(), qIdx.end(), [&](int a, int b) {
            return queries[a][2] > queries[b][2];
        });
        std::vector<std::pair<int, int>> numIndexed(n);
        for (int i = 0; i < n; ++i) numIndexed[i] = {nums[i], i};
        std::sort(numIndexed.rbegin(), numIndexed.rend());

        std::vector<long long> ans(q);
        int curNum = 0;
        for (int idx : qIdx) {
            int l = queries[idx][0], r = queries[idx][1], thresh = queries[idx][2];
            while (curNum < n && numIndexed[curNum].first >= thresh) {
                bit.update(numIndexed[curNum].second, numIndexed[curNum].first);
                curNum++;
            }
            ans[idx] = bit.rangeQuery(l, r);
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    static class Fenwick {
        int n;
        long[] tree;
        Fenwick(int n) { this.n = n; tree = new long[n + 1]; }
        void update(int idx, int delta) {
            for (++idx; idx <= n; idx += idx & (-idx)) tree[idx] += delta;
        }
        long query(int idx) {
            long s = 0;
            for (++idx; idx > 0; idx -= idx & (-idx)) s += tree[idx];
            return s;
        }
        long rangeQuery(int l, int r) { return query(r) - query(l - 1); }
    }

    public long[] goodSubsequenceQueries(int[] nums, int[][] queries) {
        int n = nums.length, q = queries.length;
        Fenwick bit = new Fenwick(n);
        Integer[] qIdx = new Integer[q];
        for (int i = 0; i < q; i++) qIdx[i] = i;
        Arrays.sort(qIdx, (a, b) -> Integer.compare(queries[b][2], queries[a][2]));
        int[][] numIndexed = new int[n][2];
        for (int i = 0; i < n; i++) { numIndexed[i][0] = nums[i]; numIndexed[i][1] = i; }
        Arrays.sort(numIndexed, (a, b) -> Integer.compare(b[0], a[0]));

        long[] ans = new long[q];
        int curNum = 0;
        for (int idx : qIdx) {
            int l = queries[idx][0], r = queries[idx][1], thresh = queries[idx][2];
            while (curNum < n && numIndexed[curNum][0] >= thresh) {
                bit.update(numIndexed[curNum][1], numIndexed[curNum][0]);
                curNum++;
            }
            ans[idx] = bit.rangeQuery(l, r);
        }
        return ans;
    }
}

function goodSubsequenceQueries(nums, queries) {
    const n = nums.length, q = queries.length;
    const tree = new Array(n + 1).fill(0);
    const update = (idx, delta) => {
        for (++idx; idx <= n; idx += idx & (-idx)) tree[idx] += delta;
    };
    const query = (idx) => {
        let s = 0;
        for (++idx; idx > 0; idx -= idx & (-idx)) s += tree[idx];
        return s;
    };
    const rangeQuery = (l, r) => query(r) - query(l - 1);

    const qIdx = Array.from({length: q}, (_, i) => i);
    qIdx.sort((a, b) => queries[b][2] - queries[a][2]);
    const numIndexed = nums.map((v, i) => [v, i]).sort((a, b) => b[0] - a[0]);

    const ans = new Array(q).fill(0);
    let curNum = 0;
    for (const idx of qIdx) {
        const [l, r, thresh] = queries[idx];
        while (curNum < n && numIndexed[curNum][0] >= thresh) {
            update(numIndexed[curNum][1], numIndexed[curNum][0]);
            curNum++;
        }
        ans[idx] = rangeQuery(l, r);
    }
    return ans;
}
